def main(argv):
    here = pathlib.Path(__file__).resolve()
    root = pathlib.Path(os.environ.get('TI_ROOT') or here.parents[3])
    evidence = here.parent
    dry = os.environ.get('DRYRUN') == '1'

    cps, ids, tee = [], [], None
    args = list(argv)
    while args:
        a = args.pop(0)
        if a == '--cp':
            if not args:
                print('--cp needs a checkpoint')
                return 2
            cps.append(args.pop(0))
        elif a == '--tee':
            if not args:
                print('--tee needs a path')
                return 2
            tee = pathlib.Path(args.pop(0))
        else:
            ids.append(a)
    known_ids = {r[0] for r in ROWS}
    bad = [c for c in cps if c not in CPS] + [i for i in ids if i not in known_ids]
    if bad:
        print(f'unknown checkpoint or row: {bad}')
        return 2
    want = [r for r in ROWS if (not cps or r[1] in cps) and (not ids or r[0] in ids)]
    if not want:
        print('no rows selected')
        return 2

    out = []

    def say(line):
        print(line)
        out.append(line)

    label = '-'.join(cps + ids) if (cps or ids) else 'all'
    say(f'020 test-impact-edit: {len(want)} of {len(ROWS)} rows ({label}){" DRYRUN" if dry else ""}; root {root}')
    texts, gone, fails = {}, set(), 0
    for rid, cp, rel, old, new, n in want:
        path = root / rel
        if old == RETIRE:
            exists = rel not in gone and path.exists()
            if exists != bool(n):
                say(f'FAIL {rid} {cp} {rel} RETIRE: exists={exists} (expected {bool(n)})')
                fails += 1
                continue
            gone.add(rel)
            texts.pop(rel, None)
            say(f'OK {rid} {cp} {rel} RETIRE (exists; {"would delete" if dry else "deleting"})')
            continue
        if rel in gone or not path.exists():
            say(f'FAIL {rid} {cp} {rel} x0 (expected {n}): file missing or retired')
            fails += 1
            continue
        text = texts[rel] if rel in texts else path.read_text(encoding='utf-8')
        got = text.count(old)
        if got != n:
            say(f'FAIL {rid} {cp} {rel} x{got} (expected {n}): {old[:70]!r}')
            fails += 1
            continue
        texts[rel] = text.replace(old, new)
        say(f'OK {rid} {cp} {rel} x{got}')

    if fails:
        say(f'aborted: {fails} row(s) failed, nothing written')
        code = 1
    elif dry:
        say(f'DRYRUN: {len(want)} rows OK, nothing written ({len(texts)} files would change, {len(gone)} deleted)')
        code = 0
    else:
        for rel, text in texts.items():
            (root / rel).write_text(text, encoding='utf-8')
        for rel in sorted(gone):
            (root / rel).unlink()
        say(f'wrote {len(texts)} files, deleted {len(gone)}')
        code = 0
        if tee is None:
            tee = evidence / f'test-impact-edit-{label}.txt'
    if tee is not None:
        tee.write_text('\n'.join(out) + '\n', encoding='utf-8')
    return code


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
